def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper 3-colorings extending the fixed cells, modulo 998244353.

    H and W are positive, H * W <= 200, and grid contains '1', '2', '3',
    and '?'. Adjacent edge-sharing cells must contain different digits.
    """
    mod = 998244353
    # Minimize the frontier: its number of possible colorings grows
    # exponentially with width, which is at most 14 after transposing.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Two bits per column store the most recently visited cell there.
    # Before a cell is processed, these are its upper and left neighbors.
    dp = {0: 1}
    for row in grid:
        for col, cell in enumerate(row):
            shift = 2 * col
            mask = 3 << shift
            choices = (1, 2, 3) if cell == '?' else (int(cell),)
            nxt = {}
            for state, count in dp.items():
                above = (state >> shift) & 3
                left = (state >> (shift - 2)) & 3 if col else 0
                cleared = state & ~mask
                for color in choices:
                    if color != above and color != left:
                        new_state = cleared | (color << shift)
                        nxt[new_state] = (nxt.get(new_state, 0) + count) % mod
            if not nxt:
                return 0
            dp = nxt
    return sum(dp.values()) % mod

