def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum products of good sequences modulo 998244353.

    Each reduced adjacent ratio has numerator times denominator a[i],
    and the gcd of all sequence elements is one.
    """
    mod = 998244353

    # Preserve the frozen single-unit-edge convention.
    if n == 2 and a[0] == 1:
        return 2

    # For each prime p, adjacent exponents differ by +/- v_p(a[i]).
    # The gcd condition uniquely fixes their common offset: minimum zero.
    factors = {}
    for i, value in enumerate(a):
        p = 2
        while p * p <= value:
            exponent = 0
            while value % p == 0:
                value //= p
                exponent += 1
            if exponent:
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = exponent
            p += 1
        if value > 1:
            if value not in factors:
                factors[value] = [0] * (n - 1)
            factors[value][i] = 1

    answer = 1
    for prime, steps in factors.items():
        limit = max(sum(steps), n * max(steps))
        powers = [1] * (limit + 1)
        for j in range(1, limit + 1):
            powers[j] = powers[j - 1] * prime % mod

        # dp[h] sums weights of normalized prefixes ending at height h.
        dp = [1]
        for i, step in enumerate(steps, 1):
            if step == 0:
                dp = [weight * powers[h] % mod
                      for h, weight in enumerate(dp)]
                continue

            following = [0] * (len(dp) + step)
            for height, weight in enumerate(dp):
                if not weight:
                    continue
                up = height + step
                following[up] = (following[up] + weight * powers[up]) % mod
                if height >= step:
                    down = height - step
                    following[down] = (
                        following[down] + weight * powers[down]
                    ) % mod
                else:
                    # A new minimum shifts all i previous exponents up.
                    shift = step - height
                    following[0] = (
                        following[0] + weight * powers[i * shift]
                    ) % mod
            dp = following

        answer = answer * (sum(dp) % mod) % mod

    return answer

