def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths with K orthogonal moves through distinct empty cells.

    Every empty cell can be a start; paths with opposite orientations count
    separately. H and W are at most 10, and K is at most 11.

    >>> count_paths(2, 2, 2, ['.#', '..'])
    2
    >>> count_paths(2, 3, 1, ['.#.', '#.#'])
    0
    """
    cells = [(r, c) for r in range(H) for c in range(W)
             if grid[r][c] == '.']
    if len(cells) <= K:
        return 0

    indices = {cell: i for i, cell in enumerate(cells)}
    neighbors = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            j = indices.get((r + dr, c + dc))
            if j is not None:
                neighbors[i].append(j)

    # A path of K moves needs K + 1 cells in the same component.
    seen = [False] * len(cells)
    starts = []
    for root in range(len(cells)):
        if seen[root]:
            continue
        component = [root]
        seen[root] = True
        for cell in component:
            for nxt in neighbors[cell]:
                if not seen[nxt]:
                    seen[nxt] = True
                    component.append(nxt)
        if len(component) > K:
            starts.extend(component)

    visited = [False] * len(cells)

    def dfs(cell, remaining):
        if remaining == 0:
            return 1
        total = 0
        for nxt in neighbors[cell]:
            if not visited[nxt]:
                visited[nxt] = True
                total += dfs(nxt, remaining - 1)
                visited[nxt] = False
        return total

    total = 0
    for start in starts:
        visited[start] = True
        total += dfs(start, K)
        visited[start] = False
    return total

